                nt = tiles[nb]
                if nb not in destroyed_features:
                    if nt['feature'] == 'FEATURE_GEOTHERMAL_FISSURE':
                        bonus += 2
                    if nt['feature'] == 'FEATURE_REEF':
                        bonus += 2
                    if nt['feature'] == 'FEATURE_JUNGLE':
                        jungle_count += 1
                if nt['is_mountain']:
                    bonus += 1
                if nb in placed_positions:
                    district_count += 1
            bonus += floor(jungle_count / 2)
            bonus += floor(district_count / 2)

        elif district == 'HOLY_SITE':
            woods_count = 0
            district_count = 0
            for nb in neighbors:
                if nb not in tiles:
                    continue
                nt = tiles[nb]
                if nt['is_mountain']:
