                if nb not in destroyed_features and nt['feature'] == 'FEATURE_FOREST':
                    woods_count += 1
                if nb in placed_positions:
                    district_count += 1
            bonus += floor(woods_count / 2)
            bonus += floor(district_count / 2)

        elif district == 'THEATER_SQUARE':
            district_count = 0
            for nb in neighbors:
                if nb not in tiles:
                    continue
                if nb in placed_positions:
                    if placed_positions[nb] in ('ENTERTAINMENT_COMPLEX', 'WATER_PARK'):
                        bonus += 2
                    district_count += 1
            bonus += floor(district_count / 2)

        elif district == 'COMMERCIAL_HUB':
            t = tiles[pos]
            if t['has_river']:
                bonus += 2
            district_count = 0
            for nb in neighbors:
                if nb not in tiles:
                    continue
                if nb in placed_positions:
                    if placed_positions[nb] == 'HARBOR':
                        bonus += 2
                    district_count += 1
            bonus += floor(district_count / 2)

        elif district == 'HARBOR':
            district_count = 0
            for nb in neighbors:
                if nb not in tiles:
                    continue
                if nb in placed_positions:
                    if placed_positions[nb] == 'CITY_CENTER':
                        bonus += 2
                    district_count += 1
                nt = tiles[nb]
                if nt['resource'] in ('RESOURCE_FISH', 'RESOURCE_CRABS', 'RESOURCE_WHALES', 'RESOURCE_PEARLS'):
                    bonus += 1
            bonus += floor(district_count / 2)

        elif district == 'INDUSTRIAL_ZONE':
            mine_count = 0
            lumber_mill_count = 0
            district_count = 0
            for nb in neighbors:
