        elif district in ('AQUEDUCT', 'DAM', 'ENTERTAINMENT_COMPLEX', 'WATER_PARK',
                          'ENCAMPMENT', 'AERODROME', 'SPACEPORT', 'GOVERNMENT_PLAZA',
                          'PRESERVE', 'NEIGHBORHOOD', 'CANAL'):
