    return bonuses

# ===== OPTIMIZATION =====
POPULATION = 9
MAX_SPECIALTY = 1 + floor((POPULATION - 1) / 3)  # = 3

valid_cc = []
for pos, t in tiles.items():
    if can_place_city(pos[0], pos[1]):
        valid_cc.append(pos)

print(f"Max specialty districts: {MAX_SPECIALTY}")
print(f"Valid city centers: {len(valid_cc)}")

# Districts that provide adjacency bonuses
bonus_districts = ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'THEATER_SQUARE']
# Non-specialty that can boost others
nonspec_districts = ['AQUEDUCT', 'DAM']

best_total = 0
best_solution = None
count = 0

for cc in sorted(valid_cc):
    # Pre-compute valid positions for each district type
    valid_pos = {}
    for district in bonus_districts + nonspec_districts + ['ENTERTAINMENT_COMPLEX']:
        positions = []
        for pos in tiles:
            if can_place_district(pos[0], pos[1], district, cc, {}):
                positions.append(pos)
        if positions:
            valid_pos[district] = positions

    # Try combinations of up to 3 specialty + non-specialty
    available_specialty = [d for d in bonus_districts + ['ENTERTAINMENT_COMPLEX'] if d in valid_pos]
    available_nonspec = [d for d in nonspec_districts if d in valid_pos]

    for num_spec in range(1, min(MAX_SPECIALTY + 1, len(available_specialty) + 1)):
        for spec_combo in combinations(available_specialty, num_spec):
            # Build list of districts: specialty + non-specialty support
            all_districts = list(spec_combo)
            for ns in available_nonspec:
                all_districts.append(ns)

            # Recursive placement search
            def search(idx, current):
                global best_total, best_solution, count
                if idx == len(all_districts):
                    bonuses = calculate_adjacency(current, cc)
                    total = sum(bonuses.values())
                    count += 1
                    if total > best_total:
                        best_total = total
                        best_solution = {
                            'city_center': list(cc),
                            'placements': {d: list(p) for d, p in current.items()},
                            'bonuses': dict(bonuses),
                            'total': total
                        }
                    return

                district = all_districts[idx]
                if district not in valid_pos:
                    search(idx + 1, current)
                    return

                for pos in valid_pos[district]:
                    if pos == cc:
                        continue
                    occupied = False
                    for p in current.values():
                        if p == pos:
                            occupied = True
                            break
                    if occupied:
                        continue
                    if not can_place_district(pos[0], pos[1], district, cc, current):
                        continue
                    current[district] = pos
                    search(idx + 1, current)
                    del current[district]

            search(0, {})

print(f"\nEvaluated {count} placements")
print(f"\n=== BEST SOLUTION ===")
print(f"City Center: {best_solution['city_center']}")
print(f"Placements: {best_solution['placements']}")
print(f"Bonuses: {best_solution['bonuses']}")
print(f"Total Adjacency: {best_solution['total']}")

